fn main() {
    // 처음 재고와 판매한 수량이에요.
    let stock = 5;
    let sold = 2;
    // 0 대신 stock - sold를 계산해 left에 담으세요.
    // 오른쪽 식을 먼저 계산하고, 그 결과에 left라는 새 이름을 붙여요.
