tasks.solution:
fn main() {
    // 상품 하나의 가격과 배송비예요. i32는 정수 타입이에요.
    // 따옴표를 지워 price에 숫자 3000을 담으세요.
    // : i32는 price가 정수만 받는다는 표기예요. 따옴표로 감싼 글자는 담을 수 없어요.
    let price: i32 = 3000;
    // 표기가 없으면 Rust가 담은 값을 보고 정수 타입을 정해요.
    let delivery = 2500;
    // 둘 다 정수라서 더할 수 있어요. 글자와 정수는 더할 수 없어요.
    let total = price + delivery;
    println!("합계: {total}");
}

