tasks.solution:
fn main() {
    // 남은 수량은 판매 후 바뀌어요.
    // stock 선언에 mut를 붙여 다시 넣을 수 있게 하세요.
    // let만 쓰면 처음 담은 값을 바꿀 수 없어요. 다시 넣을 이름에만 mut를 붙여요.
    let mut stock = 5;
    // -=는 지금 값에서 2를 뺀 결과를 다시 stock에 넣어요. mut가 없으면 이 줄이 E0384를 내요.
    stock -= 2;
    // 다시 넣은 뒤의 stock 값이 출력돼요.
    println!("남은 수량: {stock}");
}

