}

tasks.solution:
fn main() {
    // 판매와 입고로 재고가 두 번 바뀌어요.
    // 판매에서 한 번, 입고에서 한 번 다시 넣으니 stock에는 mut가 있어요.
    let mut stock = 5;
    let sold = 2;
    let arrived = 4;
    stock -= sold;
    // 이 출력은 입고 전에 실행돼요. 그때의 stock 값이 찍혀요.
    println!("판매 후: {stock}");
    // 이 주석 아래에 stock에 arrived를 더해 다시 넣는 줄을 쓰세요.
    // +=는 지금 stock에 arrived를 더한 결과를 다시 stock에 넣어요.
    // =만 쓰면 더하지 않고 arrived 값으로 덮어써요.
    stock += arrived;
    // 입고를 더한 뒤의 stock 값이 찍혀요.
    println!("입고 후: {stock}");
}

