tasks.solution:
fn main() {
    // 지금 재고 수량이에요.
    let stock = 3;
    // true 대신 재고가 0보다 큰지 비교한 결과를 담으세요.
    // >는 왼쪽이 오른쪽보다 클 때만 참이에요. 비교한 결과가 bool 값이에요.
    // >=로 쓰면 0도 포함돼서 재고가 없을 때도 참이 돼요.
    let can_sell: bool = stock > 0;
    // bool 값은 true나 false라는 글자로 출력돼요.
    println!("판매 가능: {can_sell}");
}

