tasks.solution:
fn main() {
    // 재고 1개 중 1개를 팔아요.
    // stock 선언에 mut를 붙이세요.
    // 판매로 값이 바뀌는 stock에만 mut를 붙여요. sold는 바꾸지 않으니 그대로 둬요.
    let mut stock = 1;
    let sold = 1;
    // 판매 수량만큼 빼서 stock에 다시 넣어요.
    stock -= sold;
    // true 대신 판매 뒤 stock이 0보다 큰지 비교한 결과를 담으세요.
    // 이 줄은 빼기 뒤에 있어서 줄어든 stock으로 비교해요.
    let can_sell: bool = stock > 0;
    // 두 출력 모두 판매를 마친 뒤의 값을 보여 줘요.
    println!("남은 수량: {stock}");
    println!("판매 가능: {can_sell}");
}
